import{_ as o,a0 as d,w as p,s as r,ao as n,I as l,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"在 Ubuntu 中用 UFW 配置防火牆 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中用 UFW 配置防火牆 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中用 UFW 配置防火牆 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中用 UFW 配置防火牆 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20161201 How to Configure a Firewall with UFW","title":"在 Ubuntu 中用 UFW 配置防火牆","tag":"201701","desc":""},"relativePath":"201701/20161201 How to Configure a Firewall with UFW.md","filePath":"[post].md"}'),h={name:"201701/20161201 How to Configure a Firewall with UFW.md"};function u(g,s,c,b,k,f){const e=d("Link");return p(),r("div",null,[s[26]||(s[26]=n('<h1 id="在-ubuntu-中用-ufw-配置防火牆" tabindex="-1">在 Ubuntu 中用 UFW 配置防火牆 <a class="header-anchor" href="#在-ubuntu-中用-ufw-配置防火牆" aria-label="Permalink to “在 Ubuntu 中用 UFW 配置防火牆”">​</a></h1><p>UFW，即簡單防火牆（uncomplicated firewall），是一個 Arch Linux、Debian 或 Ubuntu 中管理防火牆規則的前端。 UFW 通過命令列使用（儘管它有可用的 GUI），它的目的是使防火牆配置簡單（即不復雜（uncomplicated））。</p><p><img src="https://www.linode.com/docs/assets/ufw_tg.png" alt="How to Configure a Firewall with UFW" title="How to Configure a Firewall with UFW"></p><h3 id="開始之前" tabindex="-1">開始之前 <a class="header-anchor" href="#開始之前" aria-label="Permalink to “開始之前”">​</a></h3>',4)),l("p",null,[s[1]||(s[1]=i("1、 熟悉我們的",-1)),a(e,{href:"https://www.linode.com/docs/getting-started"},{default:t(()=>[...s[0]||(s[0]=[i("入門",-1)])]),_:1}),s[2]||(s[2]=i("指南，並完成設置服務器主機名和時區的步驟。",-1))]),l("p",null,[s[4]||(s[4]=i("2、 本指南將盡可能使用 ",-1)),s[5]||(s[5]=l("code",null,"sudo",-1)),s[6]||(s[6]=i("。 在完成",-1)),a(e,{href:"https://www.linode.com/docs/security/securing-your-server"},{default:t(()=>[...s[3]||(s[3]=[i("保護你的服務器",-1)])]),_:1}),s[7]||(s[7]=i("指南的章節，創建一個標準用户帳户，強化 SSH 訪問和移除不必要的網絡服務。 ",-1)),s[8]||(s[8]=l("strong",null,"但不要",-1)),s[9]||(s[9]=i("跟着創建防火牆部分 - 本指南是介紹使用 UFW 的，它對於 iptables 而言是另外一種控制防火牆的方法。",-1))]),s[27]||(s[27]=n('<p>3、 更新系統</p><p><strong>Arch Linux</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Syu</span></span></code></pre></div><p><strong>Debian / Ubuntu</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update &amp;&amp; sudo apt-get upgrade</span></span></code></pre></div><h3 id="安裝-ufw" tabindex="-1">安裝 UFW <a class="header-anchor" href="#安裝-ufw" aria-label="Permalink to “安裝 UFW”">​</a></h3><p>UFW 默認包含在 Ubuntu 中，但在 Arch 和 Debian 中需要安裝。 Debian 將自動啓用 UFW 的 systemd 單元，並使其在重新啓動時啓動，但 Arch 不會。 這與告訴 UFW 啓用防火牆規則不同，因為使用 systemd 或者 upstart 啓用 UFW 僅僅是告知 init 系統打開 UFW 守護程序。</p>',7)),l("p",null,[s[11]||(s[11]=i("默認情況下，UFW 的規則集為空，因此即使守護程序正在運行，也不會強制執行任何防火牆規則。 強制執行防火牆規則集的部分",-1)),a(e,{href:"http://localhost:4567/docs/security/firewalls/configure-firewall-with-ufw#enable-the-firewall"},{default:t(()=>[...s[10]||(s[10]=[i("在下面",-1)])]),_:1}),s[12]||(s[12]=i("。",-1))]),s[28]||(s[28]=n(`<h4 id="arch-linux" tabindex="-1">Arch Linux <a class="header-anchor" href="#arch-linux" aria-label="Permalink to “Arch Linux”">​</a></h4><p>1、 安裝 UFW：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S ufw</span></span></code></pre></div><p>2、 啓動並啓用 UFW 的 systemd 單元：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start ufw</span></span>
<span class="line"><span>sudo systemctl enable ufw</span></span></code></pre></div><h4 id="debian-ubuntu" tabindex="-1">Debian / Ubuntu <a class="header-anchor" href="#debian-ubuntu" aria-label="Permalink to “Debian / Ubuntu”">​</a></h4><p>1、 安裝 UFW</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install ufw</span></span></code></pre></div><h3 id="使用-ufw-管理防火牆規則" tabindex="-1">使用 UFW 管理防火牆規則 <a class="header-anchor" href="#使用-ufw-管理防火牆規則" aria-label="Permalink to “使用 UFW 管理防火牆規則”">​</a></h3><h4 id="設置默認規則" tabindex="-1">設置默認規則 <a class="header-anchor" href="#設置默認規則" aria-label="Permalink to “設置默認規則”">​</a></h4><p>大多數系統只需要打開少量的端口接受傳入連接，並且關閉所有剩餘的端口。 從一個簡單的規則基礎開始，<code>ufw default</code>命令可以用於設置對傳入和傳出連接的默認響應動作。 要拒絕所有傳入並允許所有傳出連接，那麼運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw default allow outgoing</span></span>
<span class="line"><span>sudo ufw default deny incoming</span></span></code></pre></div><p><code>ufw default</code> 也允許使用 <code>reject</code> 參數。</p><blockquote><p>警告：</p></blockquote><blockquote><p>除非明確設置允許規則，否則配置默認 <code>deny</code> 或 <code>reject</code> 規則會鎖定你的服務器。確保在應用默認 <code>deny</code> 或 <code>reject</code> 規則之前，已按照下面的部分配置了 SSH 和其他關鍵服務的允許規則。</p></blockquote><h4 id="添加規則" tabindex="-1">添加規則 <a class="header-anchor" href="#添加規則" aria-label="Permalink to “添加規則”">​</a></h4><p>可以有兩種方式添加規則：用<strong>端口號</strong>或者<strong>服務名</strong>表示。</p><p>要允許 SSH 的 22 端口的傳入和傳出連接，你可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow ssh</span></span></code></pre></div><p>你也可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow 22</span></span></code></pre></div><p>相似的，要在特定端口（比如 111）上 <code>deny</code> 流量，你需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw deny 111</span></span></code></pre></div><p>為了更好地調整你的規則，你也可以允許基於 TCP 或者 UDP 的包。下面例子會允許 80 端口的 TCP 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow 80/tcp</span></span>
<span class="line"><span>sudo ufw allow http/tcp</span></span></code></pre></div><p>這個會允許 1725 端口上的 UDP 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow 1725/udp</span></span></code></pre></div><h4 id="高級規則" tabindex="-1">高級規則 <a class="header-anchor" href="#高級規則" aria-label="Permalink to “高級規則”">​</a></h4><p>除了基於端口的允許或阻止，UFW 還允許您按照 IP 地址、子網和 IP 地址/子網/端口的組合來允許/阻止。</p><p>允許從一個 IP 地址連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow from 123.45.67.89</span></span></code></pre></div><p>允許特定子網的連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow from 123.45.67.89/24</span></span></code></pre></div><p>允許特定 IP/ 端口的組合：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow from 123.45.67.89 to any port 22 proto tcp</span></span></code></pre></div><p><code>proto tcp</code> 可以刪除或者根據你的需求改成 <code>proto udp</code>，所有例子的 <code>allow</code> 都可以根據需要變成 <code>deny</code>。</p><h4 id="刪除規則" tabindex="-1">刪除規則 <a class="header-anchor" href="#刪除規則" aria-label="Permalink to “刪除規則”">​</a></h4><p>要刪除一條規則，在規則的前面加上 <code>delete</code>。如果你希望不再允許 HTTP 流量，你可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw delete allow 80</span></span></code></pre></div><p>刪除規則同樣可以使用服務名。</p><h3 id="編輯-ufw-的配置文件" tabindex="-1">編輯 UFW 的配置文件 <a class="header-anchor" href="#編輯-ufw-的配置文件" aria-label="Permalink to “編輯 UFW 的配置文件”">​</a></h3><p>雖然可以通過命令列添加簡單的規則，但仍有可能需要添加或刪除更高級或特定的規則。 在運行通過終端輸入的規則之前，UFW 將運行一個文件 <code>before.rules</code>，它允許迴環接口、ping 和 DHCP 等服務。要添加或改變這些規則，編輯 <code>/etc/ufw/before.rules</code> 這個文件。 同一目錄中的 <code>before6.rules</code> 文件用於 IPv6 。</p><p>還存在一個 <code>after.rule</code> 和 <code>after6.rule</code> 文件，用於添加在 UFW 運行你通過命令列輸入的規則之後需要添加的任何規則。</p><p>還有一個配置文件位於 <code>/etc/default/ufw</code>。 從此處可以禁用或啓用 IPv6，可以設置默認規則，並可以設置 UFW 以管理內置防火牆鏈。</p><h3 id="ufw-狀態" tabindex="-1">UFW 狀態 <a class="header-anchor" href="#ufw-狀態" aria-label="Permalink to “UFW 狀態”">​</a></h3><p>你可以在任何時候使用命令：<code>sudo ufw status</code> 查看 UFW 的狀態。這會顯示所有規則列表，以及 UFW 是否處於激活狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Status: active</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To                         Action      From</span></span>
<span class="line"><span>--                         ------      ----</span></span>
<span class="line"><span>22                         ALLOW       Anywhere</span></span>
<span class="line"><span>80/tcp                     ALLOW       Anywhere</span></span>
<span class="line"><span>443                        ALLOW       Anywhere</span></span>
<span class="line"><span>22 (v6)                    ALLOW       Anywhere (v6)</span></span>
<span class="line"><span>80/tcp (v6)                ALLOW       Anywhere (v6)</span></span>
<span class="line"><span>443 (v6)                   ALLOW       Anywhere (v6)</span></span></code></pre></div><h3 id="啓用防火牆" tabindex="-1">啓用防火牆 <a class="header-anchor" href="#啓用防火牆" aria-label="Permalink to “啓用防火牆”">​</a></h3><p>隨着你選擇規則完成，你初始運行 <code>ufw status</code> 可能會輸出 <code>Status: inactive</code>。 啓用 UFW 並強制執行防火牆規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw enable</span></span></code></pre></div><p>相似地，禁用 UFW 規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw disable</span></span></code></pre></div><blockquote><p>UFW 會繼續運行，並且在下次啓動時會再次啓動。</p></blockquote><h3 id="日誌記錄" tabindex="-1">日誌記錄 <a class="header-anchor" href="#日誌記錄" aria-label="Permalink to “日誌記錄”">​</a></h3><p>你可以用下面的命令啓動日誌記錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw logging on</span></span></code></pre></div><p>可以通過運行 <code>sudo ufw logging low|medium|high</code> 設計日誌級別，可以選擇 <code>low</code>、 <code>medium</code> 或者 <code>high</code>。默認級別是 <code>low</code>。</p><p>常規日誌類似於下面這樣，位於 <code>/var/logs/ufw</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sep 16 15:08:14 &lt;hostname&gt; kernel: [UFW BLOCK] IN=eth0 OUT= MAC=00:00:00:00:00:00:00:00:00:00:00:00:00:00 SRC=123.45.67.89 DST=987.65.43.21 LEN=40 TOS=0x00 PREC=0x00 TTL=249 ID=8475 PROTO=TCP SPT=48247 DPT=22 WINDOW=1024 RES=0x00 SYN URGP=0</span></span></code></pre></div><p>前面的值列出了你的服務器的日期、時間、主機名。剩下的重要信息包括：</p><ul><li><strong>[UFW BLOCK]</strong>：這是記錄事件的描述開始的位置。在此例中，它表示阻止了連接。</li><li><strong>IN</strong>：如果它包含一個值，那麼代表該事件是傳入事件</li><li><strong>OUT</strong>：如果它包含一個值，那麼代表事件是傳出事件</li><li><strong>MAC</strong>：目的地和源 MAC 地址的組合</li><li><strong>SRC</strong>：包源的 IP</li><li><strong>DST</strong>：包目的地的 IP</li><li><strong>LEN</strong>：數據包長度</li><li><strong>TTL</strong>：數據包 TTL，或稱為 time to live。 在找到目的地之前，它將在路由器之間跳躍，直到它過期。</li><li><strong>PROTO</strong>：數據包的協議</li><li><strong>SPT</strong>：包的源端口</li><li><strong>DPT</strong>：包的目標端口</li><li><strong>WINDOW</strong>：發送方可以接收的數據包的大小</li><li><strong>SYN URGP</strong>：指示是否需要三次握手。 <code>0</code> 表示不需要。</li></ul><hr>`,62)),l("p",null,[s[14]||(s[14]=i("via: ",-1)),a(e,{href:"https://www.linode.com/docs/security/firewalls/configure-firewall-with-ufw"},{default:t(()=>[...s[13]||(s[13]=[i("https://www.linode.com/docs/security/firewalls/configure-firewall-with-ufw",-1)])]),_:1})]),l("p",null,[s[18]||(s[18]=i("作者：",-1)),a(e,{href:"https://www.linode.com/docs/security/firewalls/configure-firewall-with-ufw"},{default:t(()=>[...s[15]||(s[15]=[i("Linode",-1)])]),_:1}),s[19]||(s[19]=i(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[16]||(s[16]=[i("geekpi",-1)])]),_:1}),s[20]||(s[20]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[17]||(s[17]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[23]||(s[23]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[i("LCTT",-1)])]),_:1}),s[24]||(s[24]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[i("Linux中國",-1)])]),_:1}),s[25]||(s[25]=i(" 榮譽推出",-1))])])}const C=o(h,[["render",u]]);export{m as __pageData,C as default};
